import type { AccordionIndicatorProps } from "@components/accordion";
import type { MainNavItemProps } from "../main-nav.types";

import { Divider } from "@components/divider";
import { Accordion } from "@components/accordion";
import React, { forwardRef } from "react";
import { Tooltip } from "@components/tooltip";
import { clsx } from "clsx";
import { ChevronRight as ChevronRightIcon } from "@exp-textura/icons";
import { PolymorphicRef } from "@types";

import { MainNavClasses } from "../main-nav.styles";
import { useMainNav, useMainNavItemParent } from "../hooks/use-main-nav";

import { DisplayName } from "./main-nav-menu";

const MainNavTooltip = React.memo(
  ({
    trigger,
    label,
    pushed,
  }: {
    trigger: React.ReactNode;
    label: React.ReactNode;
    pushed?: boolean;
  }) => {
    const { theme } = useMainNav();
    return (
      <Tooltip
        offset={theme.toPx("1.286rem")}
        position="right"
        styleSlots={{ triggerWrapper: { width: "100%", marginTop: pushed ? "auto" : undefined } }}
        variant="compact"
      >
        <Tooltip.Trigger>{trigger}</Tooltip.Trigger>
        <Tooltip.Content>{label}</Tooltip.Content>
      </Tooltip>
    );
  },
);

const MainNavItemInner = <C extends React.ElementType = "a">(
  {
    as,
    className,
    isCurrent,
    disableTooltip,
    customTooltip,
    pushed,
    children,
    style,
    icon,
    hoverIcon,
    ...props
  }: MainNavItemProps<C>,
  ref: React.ForwardedRef<PolymorphicRef>,
) => {
  const { dataMainNavState, collapsed } = useMainNav();
  const Component = as || "a";

  // Full children (preserve everything for rendering)
  const rawChildren = React.Children.toArray(children);
  // Children excluding the indicator (used for tooltip and icon-as-child inference)
  const childrenArray = rawChildren.filter(
    (child) =>
      ((child as React.ReactElement).type as DisplayName)?.displayName !== "MainNav.Indicator" &&
      child !== null &&
      child !== undefined,
  );
  let tooltipLabel: React.ReactNode = null;
  const childrenLength = childrenArray.length;

  // Build leading icon slot: prefer icon prop; otherwise use first child
  let leadingIcon: React.ReactNode | null = null;
  if (icon || (childrenArray.length > 0 && React.isValidElement(childrenArray[0]))) {
    const baseIcon = icon ?? childrenArray[0];
    leadingIcon = hoverIcon ? (
      <span className={MainNavClasses.iconSwap}>
        <span className={MainNavClasses.iconSwapDefault}>{baseIcon}</span>
        <span aria-hidden className={MainNavClasses.iconSwapHover}>
          {hoverIcon}
        </span>
      </span>
    ) : (
      baseIcon
    );
  }

  // Compose final children
  let renderedChildren: React.ReactNode = children;
  if (leadingIcon) {
    if (icon) {
      // icon prop provided: prepend icon, keep all original children (including indicator)
      renderedChildren = (
        <>
          {leadingIcon}
          {rawChildren}
        </>
      );
    } else if (childrenArray.length > 0) {
      // icon from children: remove the first non-indicator child from raw list, then prepend icon
      const firstNonIndicator = childrenArray[0];
      const remainingRaw = rawChildren.filter((c) => c !== firstNonIndicator);
      renderedChildren = (
        <>
          {leadingIcon}
          {remainingRaw}
        </>
      );
    }
  }

  if (icon) {
    // With icon prop, tooltip should reflect all textual/label children
    tooltipLabel = childrenLength <= 1 ? childrenArray[0] : childrenArray;
  } else {
    if (childrenLength <= 1) {
      tooltipLabel = childrenArray[0];
    } else if (childrenLength > 1) {
      // Without icon prop, assume first child is an icon, exclude it from tooltip
      tooltipLabel = childrenArray.slice(1);
    }
  }

  if (process.env.NODE_ENV !== "production" && icon && React.isValidElement(childrenArray[0])) {
    // Soft warning to help consumers avoid duplicate icons
    // eslint-disable-next-line no-console
    console.warn(
      "MainNav.Item: Both 'icon' prop and a leading child element were provided. The icon prop renders before children; consider removing the leading child icon to avoid duplication.",
    );
  }

  const commonProps = {
    className: clsx(MainNavClasses.item, className),
    "data-main-nav-state": dataMainNavState,
    "data-main-nav-item-current": isCurrent ? "true" : undefined,
    tabIndex: 0,
    style: {
      ...style,
      marginTop: pushed ? "auto" : style?.marginTop,
    },
  };

  const trigger = (
    <Component ref={ref} {...commonProps} {...props}>
      {renderedChildren}
    </Component>
  );
  return collapsed && !disableTooltip ? (
    <MainNavTooltip label={customTooltip || tooltipLabel} pushed={pushed} trigger={trigger} />
  ) : (
    trigger
  );
};

export const MainNavItem = React.memo(forwardRef(MainNavItemInner));
MainNavItem.displayName = "MainNav.Item";

export const MainNavDivider = forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    const { collapsed } = useMainNav();

    return (
      <Divider
        ref={ref}
        className={clsx(MainNavClasses.divider, className)}
        data-main-nav-state={collapsed ? "collapsed" : "expanded"}
        {...props}
      />
    );
  },
);
MainNavDivider.displayName = "MainNav.Divider";

export const MainNavIndicator: React.FC<React.PropsWithChildren | AccordionIndicatorProps> = (
  props,
) => {
  const parentType = useMainNavItemParent();

  if (parentType === "accordion") {
    return (
      <div className={MainNavClasses.indicator}>
        <Accordion.Indicator {...props} />
      </div>
    );
  }

  return <div className={MainNavClasses.indicator}>{props.children || <ChevronRightIcon />}</div>;
};
MainNavIndicator.displayName = "MainNav.Indicator";
